   "note": "Струя бьёт с той же скоростью, с какой тело падает с высоты столба, $\\sqrt{2gh}$, и плотность в ответ не входит: вода и ртуть при одинаковом уровне текут одинаково быстро. Ответ требует отверстия, много меньшего сечения сосуда; без этого пренебрежения скорость при $s/S = 0{,}3$ больше на 5 процентов. Трение на коротком пути к отверстию не успевает отнять заметную долю энергии и при числе Рейнольдса около $5\\cdot10^4$. Задача о реактивной силе достраивает картину импульсом: сила вдвое больше гидростатического давления на глубине отверстия, умноженного на его площадь, а у острого края струя сжимается примерно до $0{,}6\\,s$, и сила меньше."
