   "note": "Несжимаемость есть свойство течения, а не вещества, и условий у неё два. Скорость мала против скорости звука: плотность меняется тогда на величину порядка $(v/c)^2/2$, у воздуха на процент при 50 м/с. Течение меняется медленнее, чем звук пробегает трубу туда и обратно, за $2l/c$. Где второе нарушено, приходит гидроудар со скачком $\\rho c v$: у воды водопроводной трубы при 0,53 м/с это 7,9 бар против $\\rho v^2/2 = 140$ Па, хотя сжимается она на $3{,}6\\cdot10^{-4}$. Где модели совпадают, бритва Оккама оставляет несжимаемую, а у мгновенно закрытого крана она платит бесконечным давлением."
