   "note": "Выталкивающая сила есть сумма сил давления по поверхности тела, и подмена тела жидкостью той же формы даёт её без интеграла: вес вытесненной жидкости, для любой формы и любого поля. Подмене нужны два условия: жидкость вокруг покоится или движется как целое, без сдвига, и давит на тело со всех сторон. Кубик со стороной 10 см, прижатый ко дну метрового сосуда без зазора, вместо 9,8 Н вверх получает 1100 Н вниз. В сосуде с ускорением сила равна $\\rho V(\\vec a - \\vec g)$ и при разгоне на 2 м/с² наклонена вперёд на 11,5°, а за быстро всплывающим телом остаётся след, и подмена не работает."
