   "slug": "gidrodinamika",
   "note": "Второй закон для кубика жидкости по членам: масса единицы объёма на ускорение равна перепаду давления, весу и вязкой силе. Для течения слоями это $\\rho\\,\\partial v/\\partial t = -\\partial P/\\partial x + \\eta\\,\\partial^2 v/\\partial y^2$, и вязкий член читается так: сила тянет слой к средней скорости соседей. Установившиеся решения дают течения Куэтта и Пуазёйля, а время установления порядка $h^2/\\nu$, 100 с у слоя воды толщиной 1 см. В общей записи к ускорению добавляется член переноса $(\\vec v\\cdot\\nabla)\\vec v$, разгонявший кубик жидкости в сужении, и рядом стоит неразрывность для кубика. Из опыта взяты $\\eta$ и сам линейный закон вязкости; есть ли у трёхмерного уравнения всегда гладкое решение, остаётся открытым вопросом."
