   "note": "У вопроса два смысла. Трубу целиком можно считать без потерь, пока работа трения мала против кинетической энергии, по оценке $l \\ll \\mathrm{Re}\\,d/16$ с точностью до порядка; баланс по закону Пуазёйля даёт $\\mathrm{Re}\\,d/64$, у трубы 1 см при $\\mathrm{Re} = 1000$ около 16 см. Невязкое ядро у оси идёт по Бернулли дальше, до конца входного участка, около $0{,}06\\,\\mathrm{Re}\\,d$, 60 см, пока слой у стенки не заполнит трубу; совпадение множителей $1/16$ и $0{,}06$ случайно. Игла шприца стоит на границе, и обе формулы дают ей только оценки, струю 8–11 м/с вместо 14. Простую модель держат на коротком участке трубы, и одного числа Рейнольдса для выбора мало: решает длина против $\\mathrm{Re}\\,d$."
