   "note": "Вязкость определена опытом с доской на тонком слое и переведена в локальную форму, закон Ньютона для вязкого трения $\\tau = \\eta\\,\\partial v/\\partial y$, тем же приёмом, каким $\\sigma = E\\varepsilon$ вышло из жёсткости. Число $\\eta$ принадлежит жидкости, а площадь, слой и скорость опыту; модуль сдвига у кубика жидкости нулевой, и на сдвиг он отвечает скоростью роста угла. Под доской профиль прямой, потому что слой без ускорения при постоянном давлении получает равные силы сверху и снизу; прилипание задаёт только значения скорости у стенок. Механизм у жидкости и газа разный: с ростом температуры вязкость жидкости падает, а газа растёт. Кровь и растворы полимеров закону не подчиняются."
