   "note": "Замок главы о кинематике точки: четыре возврата языка поставлены рядом обратным ходом, от поворота к пределу, и отделены от сдачи пятой ступени. Поворот выглядит вектором и вектором не является, складываются только угловые скорости; годограф выдал величину и направление центростремительного ускорения без единой производной; обратный ход открылся классом задач, где язык говорит «нет», и на этом «нет» держится доверие к остальному; предел отношения двух малостей дал скорость в мгновение и сверх того направление касательной. Четыре возврата взяты в неподвижных осях, и пока они шли, глава пользовалась правом дифференцировать вектор по строчкам, купленным четвёртой договорённостью; на пятой ступени это право сдано сознательно, и кривизна одним числом есть сдача ступени, а не возврат записи. Третья договорённость выдана со сроком: тело отсчёта пока любое, дальше выбирать начнут законы, и системы отсчёта разделятся на два сорта."
