   "note": "Угловые скорости складываются по параллелограмму, а конечные повороты нет: кирпич, повёрнутый на $90^\\circ$ вокруг продольной и поперечной осей в разном порядке, приводит отмеченную точку в разные места. Поворот выглядит вектором и вектором не оказался; это свойство пространства, с которым приходится мириться, и ориентацию манипулятора нельзя собрать из поворотов сложением векторов. Угловые скорости всё же складываются, потому что разница двух порядков есть величина второго порядка малости по углам."
