   "note": "Интеграл от модуля скорости: те же куски разбиения, что при интегрировании скорости, только складываются длины, а не векторы. Вся разница с перемещением сидит в модуле, отсюда $s \\ge |\\Delta\\vec r|$; маятник за период проходит $4A$ при нулевом перемещении. Площадь под графиком одной проекции скорости равна пути только при движении по прямой без смены знака, и на этом стоит ловушка первой задачи темы. Малый кусок пути $ds = |\\vec v|\\,dt$ дальше работает длиной дуги в выводе нормального ускорения."
