   "slug": "kinematika",
   "note": "Кривизна как имя величины $d\\alpha/ds$, угол поворота касательной на единицу пути: свойство самой линии, не зависящее от того, быстро по ней едут или медленно; радиус кривизны обратная величина, для окружности $R$. К радиусу два маршрута. Физический: прочитать $a_n = v^2/R$ в обратную сторону, $R = v^2/a_n$, где $a_n$ есть проекция ускорения поперёк скорости; на параболе броска в вершине $R = v_x^2/g$, в наклонной точке $v^2/(g\\cos\\theta)$. Аналитический, рассказанный как вывод: $k = y''/(1 + y'^2)^{3/2}$ для $y(x)$ и $|\\vec v \\times \\vec a|/v^3$ для параметрической записи, и последняя замыкается на $v^2/a_n$; проверка на параболе даёт ту же строку. Формула-рецепт не цель, физический маршрут основной. Оба маршрута отказывают в одних и тех же местах: в точке перегиба окружности нет, в изломе нет базиса; разбор обеих точек живёт во врезке у разложения ускорения."
