   "slug": "kinematika",
   "note": "Одно условие, постоянство ускорения, и двойное интегрирование: площадь под $a(t)$, прямоугольник, даёт $\\vec v = \\vec v_0 + \\vec a t$; площадь под $v(t)$, прямоугольник с треугольником, даёт $\\vec r = \\vec r_0 + \\vec v_0 t + \\vec a t^2/2$, и квадрат времени виден по треугольнику. Вложили одно число, получили две формулы и две постоянные, которые меряют на старте. Проверки: размерность, предел $a = 0$, обратное дифференцирование. Бросок под углом: горизонтальная строка вырождается, вертикальная работает целиком, время полёта и дальность те самые, что берёт задача о мяче."
