   "note": "Предел отношения перемещения к промежутку времени: обе половины дроби уходят в ноль, а отношение садится на конечное число, и это первый случай, когда язык вернул больше вложенного. Направление приходит даром: деление на положительный скаляр направления не трогает, секущая в пределе даёт касательную, и это её определение; школьное «одна общая точка» разбито контрпримером $y = x^3$. Пока оси неподвижны, вектор дифференцируется по строчкам; в изломе касательной нет, и машина, остановившаяся в углу, показывает точку, где у скорости нет направления. Обозначения: производная модуля радиус-вектора не равна модулю скорости, подмена типовая, лечится конвенцией «символ без стрелки — модуль»."
