   "sub": "zatuhayushchie",
   "note": "Декремент меряют по двум соседним амплитудам, $d = \\ln(x_n/x_{n+1})$, и добротность определена через него, $Q = \\pi/d = \\pi N$, где $N$ число колебаний, за которые амплитуда падает в $e$ раз; рядом $Q \\approx \\omega_0/2\\gamma$. Энергетическое $Q \\approx 2\\pi E/\\Delta E$ есть отношение энергии к средней потере за радиан фазы, а не за период, и совпадает с $\\pi/d$ только при слабом затухании. Добротность меряет затухание часами самой системы: осциллятор, который по секундомеру гаснет быстрее, по счёту своих колебаний может жить дольше. На интервале, малом против $N$ периодов, трением можно пренебречь и считать колебания свободными; десятиметровому маятнику Фуко, который должен качаться три часа, нужна добротность больше $5000$. Второй смысл добротности, высоту и ширину резонансной кривой, даёт отклик на внешнюю периодическую силу."
