   "note": "Эффективная длина $l_A = I_A/(ma)$, в учебниках чаще приведённая, есть длина нити, на которой груз качается в такт с телом. Центр качания лежит на продолжении отрезка от оси к центру масс на эффективной длине, и тело, подвешенное за него, качается с тем же периодом. Взаимность доказана двойным переносом оси, а теорема Виета даёт её короче: расстояния $a$ и $b$ от центра масс до точки подвеса и центра качания суть корни одного квадратного уравнения, $a + b = l_A$ и $ab = I_C/m$. Равные периоды даёт и симметричная пара опор, $b = a$, и на ней измерение $g$ ломается: у метрового стержня с опорами в $0{,}40$ м от середины расстояние между ними $0{,}8$ м при эффективной длине $0{,}608$ м, и $g$ выходит завышенным на $31{,}5$ процента. Поэтому оборотный маятник делают несимметричным, и тогда ни центра масс, ни момента инерции знать не нужно."
