   "slug": "kolebaniya",
   "sub": "zatuhayushchie",
   "note": "Затухающий косинус с частотой $\\sqrt{\\omega_0^2 - \\gamma^2}$ и критическое решение $(A_1t + A_2)e^{-\\gamma t}$ проверяются подстановкой, без комплексных чисел. Замена $x = e^{-\\gamma t}y$ убирает трение, и режим решает знак коэффициента при $y$, тот же, что отделял колебания около равновесия от ухода от него: при слабом трении затухающие колебания, при сильном апериодический режим, на границе критический. Частота затухающих колебаний меньше собственной, а огибающая падает в $e$ раз за время $1/\\gamma$ и от жёсткости не зависит. Из покоя критический режим возвращает систему быстрее любого апериодического и на долгом хвосте быстрее колебательного, хотя в коридор пять процентов колебательный режим с $\\gamma/\\omega_0 = 0{,}7$ входит раньше, перелетев равновесие на $4{,}6$ процента. На критическое трение $2\\sqrt{mk}$ настраивают стрелку прибора и регулятор сустава робота, а в машинном обучении метод с импульсом: трение, критическое для пологой стенки оврага, сокращает число шагов в корень из отношения жёсткостей стенок."
