   "note": "Вязкое трение входит первым членом разложения силы по скорости, $-\\beta\\dot x$, так же, как возвращающая сила входила первым членом по смещению. У тела, колеблющегося в жидкости или газе, сила линейна по скорости, пока амплитуда мала против размера тела. Сухое трение меняет знак вместе со скоростью, линейного члена у него нет, и модель выбирают по опыту: при вязком трении за период амплитуда уменьшается в одно и то же число раз, при сухом на одну и ту же величину, $4\\mu_\\text{тр}g/\\omega_0^2$, и тело встаёт за конечное число колебаний. Уравнение решают динамическим методом: энергия не сохраняется и входит только мерой потерь, $dE/dt = -\\beta\\dot x^2$. Подстановка экспоненты с действительным показателем сводит задачу к квадратному уравнению, и знак $\\gamma^2 - \\omega_0^2$ делит решения на случаи."
