   "note": "Один приём контроля с двумя лицами. Первое: уравнение однородно — все слагаемые обеих частей имеют одну размерность, иначе равенство не значит ничего. Второе: аргумент логарифма, экспоненты или синуса безразмерен. Основание у обеих проверок одно, складывать и сравнивать можно только однородное, и обе ловят ошибку до вычислений. В ядре написана вторая половина: приём контроля, переносимый в любую тему: под логарифмом, экспонентой или синусом обязана стоять безразмерная комбинация; у логарифма это на практике всегда отношение к опорному значению, у синуса бывает и произведение вроде $\\omega t$, иначе формула написана неверно. Задача показывает выражение для энтропии, которое выглядит нарушением, и снимает противоречие тем, что энтропия определена с точностью до константы, а разность логарифмов складывается в логарифм отношения. Тип метода стоит по той же логике, по какой в онтологии методом назван контроль предельным случаем."
