   "slug": "termodinamika",
   "note": "Замок области: два описания газа, без молекул и через удары молекул, сведены по давлению, температуре, энергии и звуку. Давление сошлось само, оно было общим с самого начала: поток импульса молекул через площадку совпал с напряжением на грани кубика среды. Температура сошлась встречей, $\\langle\\varepsilon_\\text{пост}\\rangle = \\tfrac32 kT$, и постоянная Больцмана стала переводом кельвинов в джоули. Энергия сошлась теоремой о равнораспределении, с границей, а звук сошёлся с опытом: 343 м/с против 290 у изотермы. Договорились о трёх началах как опытных фактах, о законе разреженного газа и о модели малых молекул без притяжения; язык вернул температуру мерой энергии молекулы, $U(T)$, различие функции состояния и величин пути, уравнение адиабаты и скорость звука. «Нет» он сказал у холодного водорода, где отказывает классическая статистика, у плотного газа, который модель без притяжения не сжижает, и в рывке, где у газа нет одного давления. Окончательного определения температуры здесь нет: из четырёх ступеней пройдены две."
