   "slug": "termodinamika",
   "note": "Газ, выведенный из равновесия, возвращается в него за время релаксации, и у газа в сосуде таких времён два: давление выравнивает звук за время порядка $L/c$, температуру теплопроводность за $L^2/\\pi^2\\chi$. В сосуде 10 см у воздуха при 300 К это 0,29 мс и 46 с. Процесс квазистатический, если параметры меняются много медленнее релаксации, и тогда он есть цепочка равновесных состояний, линия на диаграмме. Песок, снятый с поршня по песчинке, даёт такой процесс, сброшенный разом нет, и медленная утечка через малое отверстие тоже нет: равновесной должна быть вся система на каждом шаге. По бритве Оккама равновесную модель берут, пока процесс медленнее выравнивания давления; в рывке она ошибается в главном, работа через давление газа не считается, а первое начало остаётся верным. Неравновесность не то же, что необратимость."
