   "slug": "termodinamika",
   "note": "Встреча двух записей давления даёт $k = R/N_A$, газовую постоянную в расчёте на одну молекулу. Сама $k$ масштаба энергии не задаёт, его задаёт произведение $kT$, энергия теплового движения молекулы: при 300 К $kT = 0{,}0259$ эВ. С 1954 по 2019 год кельвин держала одна точка воды, тройная, а с 2019 года $k = 1{,}380649\\cdot10^{-23}$ Дж/К задано точно и само определяет кельвин; вместе с точным числом Авогадро точна и газовая постоянная, $R = kN_A = 8{,}314$ Дж/(моль·К)."
