   "slug": "termodinamika",
   "note": "Настоящие молекулы вблизи отталкиваются, а дальше притягиваются, и притяжение есть хвост потенциала двух молекул. Молекулу у стенки соседи тянут назад, поэтому притяжение снижает давление против модели идеального газа, а собственный объём молекул его повышает: у азота при нормальных условиях по оценке Ван-дер-Ваальса примерно на 0,3 и 0,2 процента, а измеренное $PV$ воздуха отличается от $\\nu RT$ примерно на 0,06 процента. Притяжение охлаждает газ, расширяющийся в пустоту: азот при расширении вдвое с атмосферного давления остывает на 0,14 К, с 22 атмосфер примерно на 3 К, а газ твёрдых шаров без притяжения не остывает при любой плотности. Сжижает газ притяжение, размер молекул тут ни при чём."
