   "slug": "termodinamika",
   "note": "Удары молекул дали давление $P = \\tfrac23 n\\langle\\varepsilon_\\text{пост}\\rangle$ без температуры, газовый термометр дал $PV = \\nu RT$ без молекул. Молекулы входят во вторую запись, когда моли переводят в молекулы, $n = \\nu N_A/V$, и давление у газа одно, поэтому $\\langle\\varepsilon_\\text{пост}\\rangle = \\tfrac32 kT$ с $k = R/N_A$. Связь не принята по договорённости, договором задан только размер градуса: две записи получены порознь и сошлись. При 300 К средняя энергия поступательного движения $6{,}2\\cdot10^{-21}$ Дж, а корень из среднего квадрата скорости молекулы воздуха 508 м/с. Из четырёх ступеней, которыми курс вводит температуру, это вторая: газовая температура верна, пока газ идеален, и в классическом пределе, а ноль кельвина остаётся нулём классической картины."
