   "slug": "termodinamika",
   "note": "Системы различают по обмену с окружением. Изолированная не обменивается ни энергией, ни частицами, как газ в жёстком сосуде с теплоизолирующими стенками. Закрытая обменивается энергией, но не частицами, как термос с чаем, а открытая и тем и другим, как чашка на столе. Граница системы решает ответ: воздух в комнате при нагреве и постоянном давлении есть открытая система, и его внутренняя энергия не меняется, потому что нагретый воздух частью уходит через щели, а порция воздуха, бывшая в комнате до нагрева, получила бы около $2{,}2\\cdot10^5$ Дж."
