   "sub": "vrashchenie-vokrug-osi",
   "note": "Аналог второго закона для угла: $I_z\\varepsilon = M_z$, знак задаёт правило правой руки, роль силы играет момент, роль массы момент инерции. Сходство $p = mv$ и $L_z = I_z\\omega$ держится только в проекции. Когда $M_z = 0$, сохраняется $L_z$, даже если другие проекции момента сил есть: человек на скамье Жуковского сводит гантели с $0{,}75$ до $0{,}20$ м, момент инерции падает с $3{,}85$ до $1{,}76$ кг·м², угловая скорость растёт с $3{,}14$ до $6{,}87$ рад/с. Энергия растёт с $19{,}0$ до $41{,}6$ Дж, потому что человек с гантелями есть система тел, а не твёрдое тело, и работу совершают мышцы."
