   "slug": "tverdoe-telo",
   "sub": "proizvolnoe-dvizhenie",
   "note": "Собственные направления тензора, в которых центробежные моменты равны нулю: только вдоль них $\\vec L\\parallel\\vec\\omega$, и равномерному вращению не нужен момент опор. У симметричной матрицы три вещественных главных момента и три перпендикулярные оси; если два момента равны, главной оказывается любая ось в их плоскости, а у шара и куба относительно центра любая. Главные оси принадлежат точке: вертикаль стержня на шарнире не главная относительно шарнира и главная относительно точки на $2l\\cos\\beta/3$ ниже него. Свободное тело вращается вокруг неподвижной оси, только если ось главная центральная. Относительно центра масс главные оси совпадают с главными компонентами облака масс, порядок обратный."
