   "note": "Шесть тел одной массы и одного радиуса скатываются по склону: обруч, тонкая сфера, диск, шар, колесо со спицами и брусок без трения. Ускорение $g\\sin\\theta/(1+\\beta)$ и порог трения покоя $\\mu_{\\min} = \\beta\\operatorname{tg}\\theta/(1+\\beta)$ задаёт коэффициент $\\beta = I/(mR^2)$, то есть форма, а не масса и не размер. Один опыт закрывает и зависимость момента инерции от распределения массы, и независимость скатывания от массы."
