   "note": "Замок области: четыре тела в одной таблице, и у каждого видно, стоит ли ось, лежит ли на ней момент импульса и кто даёт момент. У гантели на подшипниках и у стержня на шарнире момент дают подшипники и тяжесть, $2{,}0$ и $4{,}25$ Н·м; у тела без опор момента никто не даёт, и неподвижной остаётся лишь ось, на которой лежит $\\vec L$; у волчка ось прецессирует. Во всех строках читается один закон, $d\\vec L/dt = \\vec M$. Договорились о неизменных расстояниях, и язык вернул ориентацию тремя углами, распределение массы десятью числами, момент опор и свободные оси. «Нет» он сказал там же, где у трёх тел: тяжёлое тело с неподвижной точкой решается только в трёх случаях."
