   "sub": "ploskoe-dvizhenie",
   "note": "Точка касания покоится относительно опоры, поэтому скорость центра и угловая скорость связаны как $v = \\omega R$, а после дифференцирования так же связаны ускорения. Условие держится, пока сила трения покоя не превысила $\\mu N$. На склоне телу с большим $\\beta = I_C/(mR^2)$ нужно больше трения, $\\mu \\ge \\beta\\operatorname{tg}\\theta/(1+\\beta)$: на $30^\\circ$ обручу не меньше $0{,}29$, шару хватает $0{,}17$. Если трения не хватает, тело проскальзывает, как катушка с нитью под критическим углом при тяге больше $0{,}395\\,mg$ и $\\mu = 0{,}3$: центр едет к руке, а обод крутится в обратную сторону. Тогда точка касания движется по опоре: при юзе вперёд, при буксовании назад. Привычное уравнение моментов относительно точки касания законно у однородного круглого тела и неверно у обруча с грузом на ободе, где ошибка достигает $45$ процентов. Ускорение скатывания $g\\sin\\theta/(1+\\beta)$ задаёт распределение массы, а не масса и не радиус: с одной горки первым придёт шар, обод последним."
