   "note": "Свободное тело вращается как угодно, а ось вращения остаётся неподвижной только в одном случае: если на ней лежит момент импульса. Поперечную часть $\\vec L$ повернуть некому, поэтому равномерное вращение вокруг неподвижной оси возможно, только если $\\vec\\omega\\parallel\\vec L$, то есть вокруг главной центральной оси; иначе ось ходит вокруг неподвижного $\\vec L$. У тела с тремя разными главными моментами вокруг крайних осей малое отклонение остаётся малым, вокруг средней растёт как $e^{\\lambda t}$, и тело кувыркается: брусок $1:2:3$ переворачивается каждые $3{,}7$–$4{,}1$ оборота, брошенный телефон первый раз через $0{,}3$–$0{,}5$ с. Устойчивость крайних осей принадлежит идеальному телу. С внутренним трением остаётся ось наибольшего момента, потому что при том же $|\\vec L|$ энергия $L^2/2I$ там наименьшая."
