   "note": "Весь вектор $\\vec L$ связан с угловой скоростью матрицей $\\hat I$, и одним числом это не записывается: поперечную часть $\\omega(I_{xz};\\,I_{yz})$ задают центробежные моменты, то есть то, как разложена масса, и она есть даже при постоянной угловой скорости. Матрицу делает тензором закон преобразования $\\hat I' = R\\hat I R^{\\mathsf T}$ при повороте осей: на диагонали стоят осевые моменты, главными они становятся только в главных осях, а сохраняется при повороте один след. Тензор принадлежит точке, неподвижной точке тела или центру масс. В осях тела он постоянен, и это причина уравнений Эйлера. Гантель под углом к оси есть тот самый случай, ради которого тензор и заводят."
