   "slug": "tverdoe-telo",
   "sub": "proizvolnoe-dvizhenie",
   "note": "Тело с неподвижной точкой переводится в любое положение одним поворотом вокруг оси через эту точку, поэтому ориентацию задают три числа: двумя углами направление оси в теле, как широту и долготу на глобусе, третьим поворот вокруг этой оси. У свободного тела теорема применяется к полюсу, а перемещение складывается из переноса и поворота. Два конечных поворота снова дают один, но порядок важен: $90^\\circ$ вокруг неподвижной оси $x$ и затем $90^\\circ$ вокруг $y$ дают $120^\\circ$ вокруг одной оси, в обратном порядке $120^\\circ$ вокруг другой, а сумма векторов дала бы $127{,}3^\\circ$. Для сети, которая предсказывает ориентацию, непрерывная запись поворота требует пяти или шести чисел, а не трёх или четырёх."
