   "note": "Приёмов шесть, и каждый проверяется числом: прямое интегрирование (стержень вокруг середины), перенос оси (тот же стержень вокруг конца), аддитивность относительно одной оси, слои и кольца (шар и диск), полярный момент относительно точки, который отдаёт тонкую сферу в три строки, и правило перпендикулярных осей для плоской фигуры, откуда пластина $ma^2/6$. У правила два условия: фигура плоская, а три оси проходят через одну точку. Равенство трёх моментов у сферы требует однородности: у пояса по экватору моменты разные."
