   "sub": "giroskopy",
   "note": "Момент внешней силы поворачивает вектор момента импульса, почти не меняя его модуль, и ось уходит вбок вместо того, чтобы падать. Вывод идёт через конус: конец $\\vec L$ бежит по горизонтальной окружности радиуса $L\\sin\\theta$, отсюда $\\vec M = \\vec\\Omega\\times\\vec L$ и $\\Omega = mga/(I_\\parallel\\omega_\\parallel)$. Наклон сокращается, потому что $a$ отложено вдоль оси от опоры до центра масс, и плечо $a\\sin\\theta$ несёт тот же синус, что и радиус окружности. Задача про пропеллер читает ту же формулу в обратную сторону: принудительный поворот оси требует момента, и он приходит на вал. Ось Земли так же обходит конус под моментом Солнца и Луны на экваториальное утолщение, и оборот занимает около $26$ тысяч лет."
