   "slug": "volny",
   "note": "Скорость $c = \\sqrt{E/\\rho}$ выводится двумя путями: из импульса куска стержня, который успел прийти в движение, и из волнового уравнения цепочки грузов на пружинках; у стали 5,1 км/с, метр звук проходит за 0,2 мс. Под постоянной силой торец стержня сразу едет с постоянной скоростью $F/\\rho c S$ и до прихода эха не разгоняется, а потом едет ступенями; напряжение на фронте $\\rho c v$ собрано из чисел вещества. Тонкому стержню хватает модуля Юнга, в толще тела продольный звук быстрее, у стали около 5,9 км/с. Та же выкладка с модулем всестороннего сжатия описывает гидроудар. В газе модуль даёт первое начало: сжатие в волне адиабатическое, $K = \\gamma P$, и у воздуха при 20 °C выходит 343 м/с."
