   "from": "c-sdvig-i-kruchenie",
   "to": "c-obobshchennyj-zakon-guka",
   "type": "выводится-из",
   "note": "удлинение вдоль растянутой диагонали считается по закону для трёх осей, $\\tau(1+\\mu)/E$, и равно геометрическому $\\gamma/2$"
