   "from": "c-sila-arhimeda",
   "to": "c-svobodnaya-poverhnost",
   "type": "пререквизит",
   "note": "в сосуде с ускорением сила Архимеда равна $\\rho V(\\vec a - \\vec g)$, минус объём на градиент давления разгоняющегося сосуда"
