   "from": "c-uravnenie-navie-stoksa",
   "to": "c-neszhimaemoe-techenie",
   "type": "пререквизит",
   "note": "уравнение записано для несжимаемой жидкости, и несжимаемость в нём договорённость со своими двумя условиями"
