   "from": "c-demonstraciya-vyazkost",
   "to": "c-uravnenie-navie-stoksa",
   "type": "демонстрирует",
   "note": "разгон слоя из покоя: ускорение слоя пропорционально отличию его скорости от средней по соседям"
