   "from": "c-svobodnye-osi",
   "to": "c-glavnye-osi",
   "type": "выводится-из",
   "note": "неподвижная ось свободного тела возможна, только если $\\vec\\omega\\parallel\\vec L$, то есть вдоль главной центральной оси"
